    { name: 'Hank Wilson',     email: 'hank.wilson@example.com',     role: 'Viewer' },
    { name: 'Ivy Taylor',      email: 'ivy.taylor@example.com',      role: 'Admin' },
    { name: 'Jack Thomas',     email: 'jack.thomas@example.com',     role: 'Viewer' },
    { name: 'Karen White',     email: 'karen.white@example.com',     role: 'Editor' },
    { name: 'Leo Harris',      email: 'leo.harris@example.com',      role: 'Viewer' },
    { name: 'Mia Clark',       email: 'mia.clark@example.com',       role: 'Admin' },
    { name: 'Nathan Lewis',    email: 'nathan.lewis@example.com',    role: 'Editor' },
    { name: 'Olivia Hall',     email: 'olivia.hall@example.com',     role: 'Viewer' },
    { name: 'Paul Allen',      email: 'paul.allen@example.com',      role: 'Admin' },
    { name: 'Quinn Young',     email: 'quinn.young@example.com',     role: 'Viewer' },
    { name: 'Rachel King',     email: 'rachel.king@example.com',     role: 'Editor' },
    { name: 'Sam Wright',      email: 'sam.wright@example.com',      role: 'Viewer' },
    { name: 'Tina Scott',      email: 'tina.scott@example.com',      role: 'Admin' },
  ];

  const PAGE_SIZE = 10;
  let currentPage = 0;
  let sortField = null;
  let sortDirection = 'asc'; // 'asc' | 'desc'

  const table      = document.getElementById('userTable');
  const pagination = document.getElementById('userPagination');

  /* ── sorting ─────────────────────────────────────────── */
  function sortedUsers() {
    if (!sortField) return [...users];
    return [...users].sort((a, b) => {
      const valA = a[sortField].toLowerCase();
      const valB = b[sortField].toLowerCase();
      if (valA < valB) return sortDirection === 'asc' ? -1 : 1;
      if (valA > valB) return sortDirection === 'asc' ? 1 : -1;
      return 0;
    });
  }

  /* ── rendering ───────────────────────────────────────── */
  function render() {
    const sorted = sortedUsers();
    const start  = currentPage * PAGE_SIZE;
    const page   = sorted.slice(start, start + PAGE_SIZE);

    // Build the table body
    table.fields = [
      { label: 'Name',  field: 'name',  sortable: true,  sortDirection: sortField === 'name'  ? sortDirection : undefined },
      { label: 'Email', field: 'email', sortable: true,  sortDirection: sortField === 'email' ? sortDirection : undefined },
      { label: 'Role',  field: 'role',  sortable: true,  sortDirection: sortField === 'role'  ? sortDirection : undefined },
    ];
    table.rows = page;

    // Update pagination
    pagination.setAttribute('total-elements', users.length);
    pagination.setAttribute('page-size', PAGE_SIZE);
    pagination.setAttribute('start-element', start);
  }

  /* ── events ──────────────────────────────────────────── */
  // Sort column click
  table.addEventListener('scale-sort', (e) => {
    const { field, direction } = e.detail;
    if (sortField === field) {
      sortDirection = sortDirection === 'asc' ? 'desc' : 'asc';
    } else {
      sortField = field;
      sortDirection = direction || 'asc';
    }
    currentPage = 0;
    render();
  });

  // Pagination change
  pagination.addEventListener('scale-pagination', (e) => {
    const { startElement } = e.detail;
    currentPage = Math.floor(startElement / PAGE_SIZE);
    render();
  });

  /* ── initial render ──────────────────────────────────── */
  render();
</script>

<style>
