And if you prefer a reusable **Lit web component** wrapper:

```js
import { LitElement, html, css } from 'lit';
import '@scale-ds/scale-design-system';

class AnnouncementBanner extends LitElement {
  static properties = {
    message: { type: String },
    link: { type: String, attribute: 'link-href' },
    linkText: { type: String, attribute: 'link-text' },
    _visible: { state: true },
  };

  static styles = css`
    :host {
      display: block;
      width: 100%;
    }

    :host([hidden]) {
      display: none;
    }

    .banner {
      display: flex;
      align-items: center;
      justify-content: center;
      width: 100%;
      padding: var(--sc-spacing-3) var(--sc-spacing-6);
      background-color: var(--sc-color-primary);
      color: var(--sc-color-on-primary);
      font: var(--sc-typography-body-short);
      position: relative;
      box-sizing: border-box;
    }

    .banner a {
      color: inherit;
      font-weight: bold;
      text-decoration: underline;
    }

    sc-icon-button {
      position: absolute;
      right: var(--sc-spacing-4);
      --sc-icon-button-color: var(--sc-color-on-primary);
    }
  `;

  constructor() {
    super();
    this.message = '';
    this.link = '';
    this.linkText = 'Learn more';
    this._visible = true;
  }

  _dismiss() {
    this._visible = false;
    this.dispatchEvent(new CustomEvent('sc-dismiss', { bubbles: true, composed: true }));
  }

  render() {
    if (!this._visible) return null;

    return html`
      <div class="banner" role="banner" aria-live="polite">
        <span>
          ${this.message}
          ${this.link
            ? html` <a href="${this.link}">${this.linkText}</a>`
            : ''}
        </span>
        <sc-icon-button
          name="action-circle-close"
          size="small"
          variant="ghost"
          aria-label="Dismiss announcement"
          @click="${this._dismiss}"
        ></sc-icon-button>
      </div>
    `;
  }
}

customElements.define('announcement-banner', AnnouncementBanner);
```

**Usage:**

```html
<announcement-banner
  message="🎉 We're launching our new platform on September 15 —"
  link-href="/learn-more"
  link-text="Learn more"
  @sc-dismiss="${() => console.log('Banner dismissed')}"
></announcement-banner>
```

