And to wire up validation so that the end date can't precede the start date:

```js
const startPicker = document.getElementById('start-date');
const endPicker = document.getElementById('end-date');

startPicker.addEventListener('scChange', (e) => {
  const startValue = e.detail.value;
  // Set the min attribute on the end picker so it can't go before the start
  if (startValue) {
    endPicker.setAttribute('min', startValue);
  }
});

endPicker.addEventListener('scChange', (e) => {
  const endValue = e.detail.value;
  // Set the max attribute on the start picker so it can't go after the end
  if (endValue) {
    startPicker.setAttribute('max', endValue);
  }
});
```

