    /* ── Helpers ──────────────────────────────────── */

    function getCode() {
      return fields.map((f) => f.value?.trim() ?? '').join('');
    }

    function updateButton() {
      const code = getCode();
      verifyBtn.disabled = code.length !== 6 || !/^\d{6}$/.test(code);
    }

    function focusField(index) {
      fields[index]?.focus();
    }

    /* ── Input handler (typing + paste) ──────────── */

    fields.forEach((field, i) => {
      // Only allow single digits
      field.addEventListener('sc-input', (e) => {
        let val = field.value.replace(/\D/g, '');
        field.value = val.charAt(0) ?? '';
        updateButton();

        // Auto-advance on valid digit
        if (field.value && i < 5) {
          focusField(i + 1);
        }
      });

      // Backspace moves to previous field
      field.addEventListener('keydown', (e) => {
        if (e.key === 'Backspace' && !field.value && i > 0) {
          focusField(i - 1);
        }
        // Arrow-key navigation
        if (e.key === 'ArrowLeft' && i > 0) {
          e.preventDefault();
          focusField(i - 1);
        }
        if (e.key === 'ArrowRight' && i < 5) {
          e.preventDefault();
          focusField(i + 1);
        }
      });

      // Paste: spread digits across all boxes
      field.addEventListener('paste', (e) => {
        e.preventDefault();
        const pasted = (e.clipboardData.getData('text') || '').replace(/\D/g, '');
        if (!pasted) return;

        for (let j = 0; j < 6; j++) {
          fields[j].value = pasted[j] ?? '';
        }
        // Focus the last filled field or the next empty one
        const nextEmpty = fields.findIndex((f) => !f.value);
        focusField(nextEmpty === -1 ? 5 : nextEmpty);
        updateButton();
      });
    });

    /* ── Verify action ───────────────────────────── */

    verifyBtn.addEventListener('click', () => {
      const code = getCode();
      console.log('Verification code submitted:', code);
      // → call your verification API here
    });
  })();
</script>
```

### What's included

| Feature | Detail |
|---|---|
| **One box per digit** | Six `sc-text-field` inputs, each limited to a single numeric character |
| **Auto-advance** | Focus jumps to the next field as soon as a digit is typed |
| **Backspace navigation** | Pressing ⌫ on an empty field moves focus back |
| **Arrow-key navigation** | ← / → moves between fields |
| **Paste support** | Pasting `123456` from clipboard fills all six fields at once |
| **Numeric keyboard** | `inputmode="numeric"` brings up the number pad on mobile |
| **Accessibility** | Each field has a unique `aria-label` ("Digit 1" … "Digit 6") |
| **Verify button** | Stays `disabled` until all 6 digits are filled |
| **Scale tokens** | Uses `--sc-spacing-*`, `--sc-typography-*`, and `--sc-color-*` tokens throughout |

