import { LitElement, html, css } from 'lit';
import '@scale-ds/scale-design-system';

class CollaboratorGroup extends LitElement {
  static properties = {
    collaborators: { type: Array },
    maxVisible:    { type: Number, attribute: 'max-visible' },
  };

  static styles = css`
    :host { display: inline-flex; align-items: center; }

    .group { display: flex; align-items: center; }

    .wrapper {
      position: relative;
      margin-left: -10px;
      transition: transform 0.15s ease;
      z-index: 1;
      cursor: pointer;
    }
    .wrapper:first-child { margin-left: 0; }
    .wrapper:hover { transform: translateY(-3px); z-index: 10; }

    .avatar {
      width: 36px; height: 36px;
      border-radius: 50%;
      border: 2px solid var(--scl-color-background-standard);
      display: flex; align-items: center; justify-content: center;
      font: var(--scl-font-label-small);
      color: var(--scl-color-text-on-color);
      text-transform: uppercase;
      box-sizing: border-box;
      background-size: cover; background-position: center;
    }

    .dot {
      position: absolute; bottom: 0; right: 0;
      width: 10px; height: 10px;
      border-radius: 50%;
      border: 2px solid var(--scl-color-background-standard);
      background-color: var(--scl-color-success-standard);
    }
    .dot.idle { background-color: var(--scl-color-warning-standard); }

    .overflow {
      margin-left: -10px; z-index: 0;
      width: 36px; height: 36px;
      border-radius: 50%;
      border: 2px solid var(--scl-color-background-standard);
      background: var(--scl-color-background-raised);
      color: var(--scl-color-text-standard);
      font: var(--scl-font-label-small);
      display: flex; align-items: center; justify-content: center;
      cursor: pointer; box-sizing: border-box;
    }
    .overflow:hover { background: var(--scl-color-background-hover); }
  `;

  /* rotating palette */
  static COLORS = ['#1063e0', '#cb2a2a', '#1d8435', '#8b5cf6', '#0ea5e9', '#d97706'];

  constructor() {
    super();
    this.collaborators = [];
    this.maxVisible = 4;
  }

  _initials(name) {
    return name.split(' ').map(w => w[0]).join('').slice(0, 2);
  }

  render() {
    const visible  = this.collaborators.slice(0, this.maxVisible);
    const overflow = this.collaborators.slice(this.maxVisible);

    return html`
      <div class="group" aria-label="Document collaborators">
        ${visible.map((c, i) => html`
          <div class="wrapper" style="z-index: ${visible.length - i}">
            <sc-tooltip content="${c.name} — ${c.status === 'idle' ? 'idle' : 'editing now'}" placement="top">
              <div class="avatar"
                   style="${c.avatarUrl
                     ? `background-image: url('${c.avatarUrl}')`
                     : `background-color: ${CollaboratorGroup.COLORS[i % 6]}`}">
                ${c.avatarUrl ? '' : this._initials(c.name)}
                <span class="dot ${c.status === 'idle' ? 'idle' : ''}"></span>
              </div>
            </sc-tooltip>
          </div>
        `)}

        ${overflow.length > 0 ? html`
          <sc-tooltip content="${overflow.map(c => c.name).join(', ')}" placement="top">
            <div class="overflow"
                 role="button" tabindex="0"
                 aria-label="${overflow.length} more collaborators">
              +${overflow.length}
            </div>
          </sc-tooltip>
        ` : ''}
      </div>
    `;
  }
}

customElements.define('collaborator-group', CollaboratorGroup);
```

